[3362]={["atomIDs"]={"3362:description:1-39","3362:description:41-74","3362:description:79-138","3362:description:140-230","3362:description:235-357","3362:description:359-457","3362:description:459-480","3362:description:482-493","3362:objective:1-95"},["opening"]="Tran'rek wanted access to Thistleshrub Valley but distrusted the strange creatures there. An attack on gnarled thistleshrubs and rootshapers might persuade him to attempt the journey again.",["pending"]="{actor} would confront eight Gnarled Thistleshrubs and eight Thistleshrub Rootshapers.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed Tran'rek's assignment against eight of each specified thistleshrub kind.",["sourceClassMask"]="?",["sourceHash"]="88602448730491b9e98903539e1dc8342828822d354ee2a2d6abb67316661749",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3364]={["atomIDs"]={"3364:description:1-4","3364:description:7-160","3364:description:163-219","3364:description:224-237","3364:description:240-261","3364:description:264-370","3364:description:373-437","3364:description:442-494","3364:objective:1-97"},["opening"]="Nori's first delivery had left Durnan's mornbrew perilously close to cooling. Anvilmar lay northeast, and the cup would stay scalding for only five more minutes.",["pending"]="{actor} would hurry the Scalding Mornbrew to Durnan before it cooled.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Scalding Mornbrew to Durnan Furcutter within five minutes.",["sourceHash"]="ccea0f317bd77ea80779190de6f6d82a244023ef608ae274989b85a266b633bf",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3365]={["atomIDs"]={"3365:description:1-22","3365:description:25-131","3365:description:136-218","3365:objective:1-37"},["opening"]="Durnan had finished his hot mornbrew. Nori's mug still needed to make the return journey, a small piece of unfinished work after the hurried delivery.",["pending"]="{actor} planned to return Nori's empty mug.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned Nori's Mug to Nori Pridedrift.",["sourceHash"]="ce8e77b872c441d71ff4451f194383adbf810b48ca9bc0ad9f26c194b86e4119",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3367]={["aftermath"]="Dorius was shot and dropped a letter. His plea to reach Ironforge had ended before the hoped-for return.",["atomIDs"]={"3367:description:1-16","3367:description:21-42","3367:description:44-50","3367:description:52-66","3367:description:68-84","3367:description:86-96","3367:description:98-108","3367:description:113-141","3367:description:143-154","3367:objective:1-34"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"3367:completion:1-51"},["minimumStage"]=2,["objectiveSummary"]="Help the wounded Dorius attempt to return to Ironforge.",["opening"]="Dorius was bleeding internally and scarcely able to remain steady. Getting him back to Ironforge began as an urgent attempt to move a badly injured dwarf out of danger.",["pending"]="{actor} would help Dorius on the journey toward Ironforge.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} followed Dorius's attempted escape to its violent end.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="004ed444a400e57e54982a1a9a6643fc1c7ad37403349a750e9714807f9d6988",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[3368]={["aftermath"]="Thorius vowed to honor the request to help the enslaved workers.",["atomIDs"]={"3368:description:1-8","3368:description:13-57","3368:description:59-134","3368:description:139-216","3368:description:218-314","3368:description:316-347","3368:description:349-433","3368:description:438-456","3368:description:458-492","3368:description:497-503","3368:objective:1-47","3368:objective:49-79"},["endingAtomIDs"]={"3368:completion:1-29","3368:completion:34-81","3368:completion:83-93"},["opening"]="Dorius's last letter named the stones as real and held by Dark Irons. He said Lathoric used them to enslave his excavation team for work on Obsidion.",["pending"]="{actor} meant to carry the singed letter to Thorius.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Dorius's letter in Ironforge.",["sourceHash"]="e524cbd4fa77b760dc4d712291ea93d13aed73ea62047b788664ece73881988a",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3369]={["aftermath"]="Hamuul found the Dream different from what had been believed and declined to discuss the matter further.",["atomIDs"]={"3369:description:1-76","3369:description:78-176","3369:description:181-311","3369:description:316-370","3369:description:372-393","3369:description:395-412","3369:objective:1-60"},["endingAtomIDs"]={"3369:completion:1-21","3369:completion:23-102","3369:completion:107-135","3369:completion:146-156","3369:completion:158-162","3369:completion:167-206","3369:completion:208-275","3369:completion:277-336","3369:completion:341-412","3369:completion:417-465"},["opening"]="Falla saw a nightmare within a shard she called the Emerald Dream's essence. She withheld further explanation and directed it toward Hamuul's judgment.",["pending"]="{actor} meant to bring the troubling shard to Hamuul.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the shard on Elder Rise.",["sourceHash"]="4a02950ef7d1f926b1f775431fec92b8b232338cabe567d5c640fc9a79101d65",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3370]={["aftermath"]="Mathrengyl reserved the matter for the Cenarion druids and acknowledged that the Dream was not as expected.",["atomIDs"]={"3370:description:1-76","3370:description:78-176","3370:description:181-313","3370:description:319-387","3370:description:389-406","3370:description:408-425","3370:objective:1-64"},["endingAtomIDs"]={"3370:completion:1-21","3370:completion:23-102","3370:completion:107-139","3370:completion:150-160","3370:completion:162-166","3370:completion:171-210","3370:completion:212-279","3370:completion:281-344","3370:completion:349-420","3370:completion:425-473"},["opening"]="Falla's vision troubled her enough to seek a wiser druid's help. This route carried the shard toward Mathrengyl and the Cenarion Circle in Darnassus.",["pending"]="{actor} planned to deliver the shard to Mathrengyl.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the shard to Darnassus.",["sourceHash"]="e450c5f0c546e5046d77428190360dbc4a4e19beeb2ec7e362e4966d15a4d2c6",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3371]={["atomIDs"]={"3371:description:1-63","3371:description:65-124","3371:description:126-233","3371:description:238-308","3371:description:310-400","3371:description:402-430","3371:objective:1-63"},["opening"]="Thorius could not recover from Dorius's loss without pursuing the archaeologist's last wish. His enslaved unit might still be found in the Slag Pits, where the Dark Irons forced captives to work.",["pending"]="{actor} planned to find Dorius's archaeology unit in Searing Gorge.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the search for Dorius's archaeology unit.",["sourceClassMask"]="?",["sourceHash"]="318c9faa39b48aa4f8e6868d9cab9a69df2c980b11521c0915a668932a866953",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3372]={["atomIDs"]={"3372:description:1-17","3372:description:19-113","3372:description:118-149","3372:description:151-194","3372:description:196-227","3372:description:229-277","3372:description:282-317","3372:objective:1-178"},["opening"]="The dying archaeologist said the stones forced labor to continue beyond bodily death. A relic guarded by Twilight's Hammer was the key he offered for the altar.",["pending"]="{actor} intended to place the guarded artifact on the altar.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the artifact to the altar and placed it there.",["sourceHash"]="200f7e41fd85bd56bbeec0da98c4e5fbbd52e2d9d645159d6b1758834ebbfef8",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3373]={["aftermath"]="The font was corrupted too. Eranikus's plea became a cry against an encroaching nightmare, and he begged for help from another of the Green Dragonflight.",["atomIDs"]={"3373:description:1-58","3373:description:63-86","3373:description:89-160","3373:description:163-278","3373:description:281-374","3373:description:377-509","3373:objective:1-92"},["endingAtomIDs"]={"3373:completion:1-42","3373:completion:47-81","3373:completion:83-103","3373:completion:109-206","3373:completion:208-252","3373:completion:254-262","3373:completion:264-324","3373:completion:329-351","3373:completion:353-402","3373:completion:404-413","3373:completion:415-441","3373:completion:443-461","3373:completion:463-487"},["opening"]="A voice within a gem identified itself as Eranikus, keeper of the temple. He feared his hold on the Dream was slipping and pleaded for the essence font to cleanse the taint from his mind.",["pending"]="{actor} meant to place the Essence of Eranikus in the font within his Sunken Temple lair.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} placed the Essence of Eranikus in the essence font.",["sourceClassMask"]="?",["sourceHash"]="b79956d2e65bf7583c3aded905f156b5f1e52a6b3a53756443ba37cd902ff1bd",["sourceMapID"]="?",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3374]={["aftermath"]="Itharius acknowledged the choice to help, while judging that future conduct would determine its continuation.",["atomIDs"]={"3374:description:1-86","3374:description:91-249","3374:description:252-418","3374:description:423-500","3374:objective:1-116","3374:objective:119-196"},["endingAtomIDs"]={"3374:completion:1-44","3374:completion:46-201"},["opening"]="Through the oathstone, Itharius offered a part in redeeming Eranikus. The first sacrifice was relinquishing the gem that held the dragon's remaining free will.",["pending"]="{actor} planned to bring the oathstone and essence to Itharius.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered both objects to Itharius.",["sourceHash"]="c248330dafecca255d6b21117d8ad19e8c27c1a7f40f5c66d7b565c8a21c9e04",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3375]={["aftermath"]="Talvash admitted that he had a spare phial after all and retained the materials against another possible loss.",["atomIDs"]={"3375:description:7-40","3375:description:43-64","3375:description:67-102","3375:description:105-147","3375:description:150-182","3375:description:185-281","3375:description:286-387","3375:description:390-457","3375:objective:1-131"},["endingAtomIDs"]={"3375:completion:1-31","3375:completion:33-46","3375:completion:48-88","3375:completion:90-103","3375:completion:108-134","3375:completion:136-163","3375:completion:165-385","3375:completion:390-444"},["opening"]="Talvash demanded a potion, coal and nectar to replace the lost scrying phial. He claimed no spare remained available.",["pending"]="{actor} planned to supply the replacement materials.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the three components to Talvash.",["sourceHash"]="744f7ee4b465d9b3123f5d0e0034d8561c2945716bba28cb4e34af070305a94e",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3377]={["aftermath"]="Zamael accepted his captivity but insisted that a missing prayer still had to be found.",["atomIDs"]={"3377:description:1-27","3377:description:29-41","3377:objective:1-26"},["coverageQualification"]="PARTIAL_CONVERSATION_FRAME_MISSING_GOSSIP_BODY",["endingAtomIDs"]={"3377:completion:1-72"},["minimumStage"]=2,["objectiveSummary"]="Listen to Zamael's account.",["opening"]="Zamael appealed for a mortal's help and asked to be heard. His request began with a conversation rather than a journey undertaken without explanation.",["pending"]="{actor} would hear Zamael's account.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} listened to Zamael.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="006fed29489cc3612005a3c39dd19a06c682a18c4ed7a568faa95a1e18c9d5c0",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability","gossipDialogueBody"}},
[3378]={["aftermath"]="Astarii welcomed the return of a lost soul to Elune through the recovered prayer.",["atomIDs"]={"3378:description:1-27","3378:description:29-62","3378:description:67-122","3378:description:124-193","3378:description:198-269","3378:description:271-446","3378:description:448-485","3378:objective:1-72"},["endingAtomIDs"]={"3378:completion:1-35","3378:completion:37-73","3378:completion:75-121"},["opening"]="Zamael sought a golden tablet bearing his lost prayer. He expected no absolution for his acts, but wanted Astarii to hear the prayer after its recovery.",["pending"]="{actor} planned to recover the tablet for Astarii.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Zamael's prayer in Darnassus.",["sourceHash"]="2a8299d36b0efcf01dec47d9b281b080b9ca5e4336e842670680d985c1ff1881",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3379]={["atomIDs"]={"3379:description:1-73","3379:description:75-151","3379:description:156-327","3379:description:329-392","3379:description:394-406","3379:description:411-441","3379:description:446-488","3379:objective:1-69","3379:objective:71-156","3379:objective:158-222"},["opening"]="Nilith Lokrav valued the Searing Gorge's spiders as a source of shadow silk. Poachers were slaughtering them without regard for the future supply, and she ordered a search northward to stop the group.",["pending"]="{actor} planned to eliminate the five Shadow Silk Poachers and report to Nilith.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reported the removal of the Shadow Silk Poachers to Nilith Lokrav.",["sourceClassMask"]="?",["sourceHash"]="c30dbe9007077e0e8ea451d1b6eab59d2ee831c6b1c150bbb5119c286831e9dd",["sourceMapID"]="?",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3380]={["aftermath"]="Marvon confirmed that he had seen the Sunken Temple himself and offered to share what he knew.",["atomIDs"]={"3380:description:1-45","3380:description:47-134","3380:description:139-266","3380:description:271-373","3380:description:375-510","3380:objective:1-35"},["endingAtomIDs"]={"3380:completion:1-71","3380:completion:73-113","3380:completion:118-193"},["opening"]="Uzer'i spoke of spirits isolated and bound to ancient evil. He had heard of the Sunken Temple's burial beneath the earth and directed inquiry toward Marvon, last known to be studying troll ruins in Tanaris.",["pending"]="{actor} intended to find Marvon Rivetseeker in Tanaris.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} found Marvon Rivetseeker in Tanaris.",["sourceClassMask"]="?",["sourceHash"]="9ac73c3e856874fdb39905ab4e37caea941206cc7a2c6797268031438a553c60",["sourceMapID"]="?",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3382]={["aftermath"]="Beltis mourned crew lost during the battle and directed help toward the surviving passengers.",["atomIDs"]={"3382:description:1-67","3382:description:69-136","3382:description:138-155","3382:description:160-267","3382:description:269-384","3382:description:389-450","3382:description:455-495","3382:objective:1-99","3382:objective:101-136"},["endingAtomIDs"]={"3382:completion:1-15","3382:completion:17-26","3382:completion:28-98","3382:completion:100-124","3382:completion:129-192","3382:completion:197-272","3382:completion:274-367","3382:completion:369-403"},["opening"]="Beltis's vessel had barely sought anchorage when naga attacked. Their repeated return suggested an unfound objective, while scouts watched for another assault on crew and passengers.",["pending"]="{actor} meant to defend the captain and those aboard.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the defense with Beltis alive.",["sourceHash"]="35a442c699c98b75f29328ecd1a55385cb2b217b152859c9e78d1ebebedbdd2d",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3385]={["aftermath"]="Nilith judged the blow likely to deter the Undermarket's leaders. She said the satchel contained nothing she needed and left its remaining contents to its bearer.",["atomIDs"]={"3385:description:1-131","3385:description:136-153","3385:description:155-218","3385:description:220-326","3385:description:331-389","3385:description:391-435","3385:description:437-489","3385:description:494-509","3385:objective:1-45","3385:objective:47-116"},["endingAtomIDs"]={"3385:completion:1-56","3385:completion:58-131","3385:completion:136-195","3385:completion:197-234"},["opening"]="Nilith identified a wider trade behind the poaching: the Undermarket had established itself in the gorge. Trade Master Kovic's ties to the Dark Iron dwarves made him and Clunk the targets of her next strike.",["pending"]="{actor} meant to defeat Trade Master Kovic and Clunk, then return the Trader's Satchel.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the Trader's Satchel to Nilith Lokrav after completing the task against Kovic and Clunk.",["sourceClassMask"]="?",["sourceHash"]="06de3c71d67392e59b5d6590d9ff204a0209eafa16ba6ca87952ba5f66709a25",["sourceMapID"]="?",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3402]={["aftermath"]="Vizzklick welcomed the report. He described years of Kovic's undercutting of other traders through shady Undermarket dealings.",["atomIDs"]={"3402:description:1-86","3402:description:88-184","3402:objective:1-34"},["endingAtomIDs"]={"3402:completion:1-14","3402:completion:16-42","3402:completion:44-172","3402:completion:177-226","3402:completion:228-260"},["opening"]="Nilith wanted news of Kovic's defeat delivered personally to Gadgetzan. She expected Vizzklick to welcome the loss of a rival whose trade had harmed others.",["pending"]="{actor} planned to speak with Vizzklick in Gadgetzan.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Nilith Lokrav's news to Vizzklick.",["sourceClassMask"]="?",["sourceHash"]="927fc031a29f692ecda9ea52d1c59d5bc2b490076b6129ff1d53cbf028660fe5",["sourceMapID"]="?",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3441]={["aftermath"]="Kalaran asked whether the listener had heard enough and was ready to act.",["atomIDs"]={"3441:description:1-25","3441:objective:1-44"},["coverageQualification"]="PARTIAL_CONVERSATION_FRAME_MISSING_GOSSIP_BODY",["endingAtomIDs"]={"3441:completion:1-22","3441:completion:24-47"},["minimumStage"]=2,["objectiveSummary"]="Hear Kalaran Windblade's account.",["opening"]="Kalaran asked an adventurer to listen before undertaking further action. Hearing his account would precede whatever commitment he sought.",["pending"]="{actor} would hear Kalaran out.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} listened to Kalaran's account.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="2af211bfaf2347603f71929f07d014442f46823f76e237bad5fc5ca1d3438b3c",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability","gossipDialogueBody"}},
[3442]={["atomIDs"]={"3442:description:1-37","3442:description:42-113","3442:description:118-209","3442:description:214-268","3442:description:270-310","3442:description:315-409","3442:description:414-482","3442:objective:1-94"},["opening"]="Kalaran proposed attacking four sentry towers before an offensive. His plan required a special torch made first from elemental hearts and golem oil.",["pending"]="{actor} meant to gather four hearts and four globes of oil.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied Kalaran with both flame materials.",["sourceHash"]="435ce67d3925e68b316076b435242a88d000194838fc0f4933d67a2b56cad417",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3443]={["atomIDs"]={"3443:description:1-62","3443:description:64-100","3443:description:105-218","3443:description:220-312","3443:objective:1-52"},["opening"]="The flame still needed a shaft. Kalaran proposed reforging the enchanted thorium weapons carried by Dark Iron taskmasters and slavers.",["pending"]="{actor} intended to collect eight plated daggers.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the daggers to Kalaran.",["sourceHash"]="920954f6a931ab1faabc1effae90b5bf5d37a115b14d5216481eb92df340ee9c",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3444]={["aftermath"]="Marvon recognized the stone and said his memory was returning. The artifact connected the current inquiry to his earlier escape from the temple.",["atomIDs"]={"3444:description:1-60","3444:description:62-199","3444:description:201-293","3444:description:298-396","3444:description:398-454","3444:description:456-505","3444:objective:1-72"},["endingAtomIDs"]={"3444:completion:1-6","3444:completion:8-25","3444:completion:30-66"},["opening"]="Marvon recalled escaping the Sunken Temple through a chamber of serpent statues. A newly discovered round stone bore the same symbol, but it had already been shipped to his Ratchet workshop for safekeeping.",["pending"]="{actor} planned to retrieve the Stone Circle from Marvon's Ratchet workshop.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the retrieval of the Stone Circle from Marvon's workshop.",["sourceClassMask"]="?",["sourceHash"]="5d915d44f48bd83eb21186f6da197935994398033d305712b6717886156df7d3",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3445]={["atomIDs"]={"3445:description:1-128","3445:description:133-235","3445:description:237-307","3445:description:309-395","3445:description:400-461","3445:objective:1-35"},["opening"]="Angelas had heard of a temple banished far below the earth. For knowledge of the Sunken Temple, he recommended Marvon Rivetseeker, last known to be studying troll ruins in Tanaris after leaving Ratchet.",["pending"]="{actor} meant to find Marvon Rivetseeker in Tanaris.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} found Marvon Rivetseeker in Tanaris.",["sourceClassMask"]="?",["sourceHash"]="414f0243e54884d6bd934851889b98dbb01da551e51eecb14e48505ce6f3a42a",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3446]={["aftermath"]="The stone circle locked into the altar's opening. Its placement left the altar available for closer examination.",["atomIDs"]={"3446:description:1-106","3446:description:108-181","3446:description:183-227","3446:description:229-356","3446:description:358-387","3446:description:392-492","3446:objective:1-66"},["endingAtomIDs"]={"3446:completion:1-76","3446:completion:81-131","3446:completion:133-160","3446:completion:165-212"},["opening"]="Marvon recalled six serpent statues around a dangerous circular chamber. After a trap nearly killed him, he noticed an altar below and suspected it held the secret to the room.",["pending"]="{actor} intended to take Marvon's token to the Altar of Hakkar in the Sunken Temple.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} found the Altar of Hakkar in the Sunken Temple.",["sourceClassMask"]="?",["sourceHash"]="24f20d8321db2319982e83a4b4a67b157caede0c183dc4323348a37e475ca339",["sourceMapID"]="?",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3447]={["aftermath"]="A glint behind the idol's transparent eye revealed the Atal'ai treasure within the statue.",["atomIDs"]={"3447:description:1-55","3447:description:57-188","3447:description:193-255","3447:description:257-381","3447:description:386-407","3447:description:409-438","3447:description:440-502","3447:objective:1-86"},["endingAtomIDs"]={"3447:completion:1-78","3447:completion:80-130","3447:completion:132-206","3447:completion:211-244"},["opening"]="Marvon's memories of the temple were uncertain, but he believed the statues concealed treasure. Lights activated from the main altar might explain the circle, though he warned that its secrets would be guarded.",["pending"]="{actor} meant to investigate the secret of the Sunken Temple's circle of statues.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} uncovered the secret hidden in the circle of statues.",["sourceClassMask"]="?",["sourceHash"]="35df0abf97d50bab119c00152e74199d021e3d986a2f8557cca0227650e97385",["sourceMapID"]="?",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3448]={["atomIDs"]={"3448:description:1-115","3448:description:117-161","3448:description:163-295","3448:description:300-423","3448:description:428-504","3448:objective:1-28"},["opening"]="Karnik's new responsibility was Azshara, whose dangerous ruins still held answers about the past. Tymor had offered his particular interest and assistance from a nearby Ironforge home.",["pending"]="{actor} meant to speak with Tymor.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Tymor in Ironforge.",["sourceClassMask"]="?",["sourceHash"]="eaf3acc73f7dfb764333309b3c61244ef2e7fee07d0a80e25510ce2c6c07431e",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3449]={["atomIDs"]={"3449:description:1-57","3449:description:59-178","3449:description:180-237","3449:description:242-315","3449:description:317-402","3449:description:404-486","3449:objective:1-261"},["opening"]="Tymor wanted rubbings of the arcane rules and discoveries once displayed at Eldarath. A drawing kit supplied the method, while Xiggs would collect the four records from an island off Azshara's southern peninsula.",["pending"]="{actor} intended to make all four named rune rubbings and signal Pilot Xiggs for pickup.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the four-rune rubbing and pickup assignment for Tymor.",["sourceClassMask"]="?",["sourceHash"]="10c8978c78aba4e3e86d18668ee7199f495f1ecdbc3dbf88de41fdfd1ecf9ca6",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3450]={["atomIDs"]={"3450:description:1-96","3450:description:98-143","3450:description:148-253","3450:description:255-284","3450:description:286-332","3450:description:334-460","3450:description:462-509","3450:objective:1-40"},["opening"]="Tymor arranged for the rubbings to leave Azshara by air. Xiggs owed him favors and would soon patrol that coast, but the signal and landing place needed to be agreed before departure.",["pending"]="{actor} intended to speak with Xiggs Fuselighter in the Ironforge hangar.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Xiggs Fuselighter about the pickup.",["sourceClassMask"]="?",["sourceHash"]="e4fddece6e42e87655f463ae8a95d8de7d3a8dc4fe670e37179910e45162c083",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3451]={["atomIDs"]={"3451:description:1-27","3451:description:29-59","3451:description:61-72","3451:description:74-96","3451:description:98-132","3451:description:134-177","3451:description:179-190","3451:description:195-288","3451:description:290-331","3451:description:333-383","3451:description:385-408","3451:objective:1-84"},["opening"]="Xiggs selected the landing pad on a southern Azshara island. A flare gun would let him see when the rubbings were ready to collect during his patrol.",["pending"]="{actor} planned to obtain the Standard Issue Flare Gun from Xiggs.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the flare-gun exchange with Xiggs Fuselighter.",["sourceClassMask"]="?",["sourceHash"]="6aaeaea7aa9d1f887cbd478f32541e4747831fcd8d59d1eee79c4653f475f344",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3452]={["aftermath"]="Kalaran judged the symbol's foul magic suitable for his work.",["atomIDs"]={"3452:description:1-42","3452:description:47-134","3452:description:136-212","3452:description:214-297","3452:description:299-406","3452:objective:1-58"},["endingAtomIDs"]={"3452:completion:1-62"},["opening"]="A magical casing remained the torch's final component. Kalaran hoped a cult symbol carried enough enchantment to extract for the purpose.",["pending"]="{actor} planned to recover one symbol of Ragnaros.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the symbol to Kalaran.",["sourceHash"]="1d84d249c1dfafc825aef1775ef154a68611a8af8b39c224377ad37612915e06",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3453]={["aftermath"]="Kalaran announced one final task after the preparation.",["atomIDs"]={"3453:description:1-76","3453:objective:1-64"},["endingAtomIDs"]={"3453:completion:1-47"},["opening"]="Kalaran had the separate pieces and needed time to combine them. The next step required waiting while the necessary enchantments were applied.",["pending"]="{actor} meant to wait for Kalaran's work.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} waited through the torch's preparation.",["sourceHash"]="1f00eda01c09df8eac04d9f16267765a6a0b00b1ca642f82166254d5f0acb4f6",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3454]={["atomIDs"]={"3454:description:1-41","3454:description:43-64","3454:objective:1-30"},["opening"]="The prepared torch still needed to be bound to its owner. Kalaran directed its taking as that last step.",["pending"]="{actor} intended to take the prepared torch.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} took the torch.",["sourceHash"]="6e920b0c89c8801149296f00fded7565309942f9a3b8375ef410b6a6fe7c7151",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3461]={["atomIDs"]={"3461:description:1-115","3461:description:117-172","3461:description:174-221","3461:description:223-251","3461:description:253-268","3461:description:273-327","3461:description:332-368","3461:description:370-434","3461:objective:1-47"},["bridge"]="The rune records had reached the pickup. Xiggs sent the drawing kit back with its bearer, leaving Tymor to receive his tool and settle the scholar's side of the work.",["bridgeFrom"]=3449,["bridgeReplacesSetup"]=true,["opening"]="Xiggs needed no drawing kit and had no payment from Tymor. Returning the tool to Ironforge would close the practical side of the aerial pickup and allow the scholar to settle his own account.",["pending"]="{actor} meant to return Tymor's Drawing Kit.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Tymor's Drawing Kit to him in Ironforge.",["sourceClassMask"]="?",["sourceHash"]="d96e83ddc85000a25b77b6f226d847ecb2cfc5c1cfe2f1a8e7ca5903a53ce75f",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3462]={["atomIDs"]={"3462:description:1-37","3462:description:39-109","3462:objective:1-27"},["opening"]="Kalaran passed instruction to his envoy. Maltrake would explain how the torch was to be used against the sentry towers.",["pending"]="{actor} planned to consult Maltrake.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} met Kalaran's envoy.",["sourceHash"]="dbae2a5bae885e51c4d9afabeed4abddcee4b53eb0a5ac76620bb0d10a296e73",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3463]={["atomIDs"]={"3463:description:1-16","3463:description:18-194","3463:description:199-324","3463:description:329-415","3463:description:417-465","3463:objective:1-122"},["opening"]="Maltrake said the towers could not be destroyed, but long-burning fires would deny them to sentries. The torch had to be used within each fortification.",["pending"]="{actor} meant to ignite all four towers.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the fires at the four sentry towers.",["sourceHash"]="c0c1eeb82ec2e7702867041712be138e307f8b0affeff55980c2a13c3404518f",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3481]={["aftermath"]="The chest opened at a touch, leaving its contents still to be examined.",["atomIDs"]={"3481:description:1-25","3481:objective:1-15"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"3481:completion:1-30","3481:completion:32-73","3481:completion:75-108"},["minimumStage"]=2,["objectiveSummary"]="Open the locked chest.",["opening"]="A closed chest offered no explanation beyond the lock preventing its opening. Discovering what lay within required examining the container itself.",["pending"]="{actor} would attempt to open the chest.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} opened the chest.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="5d96874101aef32cb7edb670d94011caa3058bfa9a4d4b9b53752ca06127c91c",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[3501]={["atomIDs"]={"3501:description:1-173","3501:description:178-329","3501:description:334-423","3501:objective:1-88"},["opening"]="Kum'isha doubted flawed fragments could open a path home. They might still serve the draenei in other ways, so he offered an exchange for imperfect finds.",["pending"]="{actor} meant to bring an imperfect fragment to Kum'isha.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered a flawed draenethyst fragment.",["sourceHash"]="ad4667222a150bb01a8fce23cc91ec7e6bff2c7fbb4291ec23d4161753965ee8",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3502]={["atomIDs"]={"3502:description:1-61","3502:description:66-131","3502:description:136-222","3502:description:224-282","3502:description:284-329","3502:objective:1-47","3502:objective:49-118"},["opening"]="Kum'isha renewed his exchange of fragments for items from his own heap. Creatures throughout the Blasted Lands might carry material he would accept.",["pending"]="{actor} intended to trade another imperfect fragment.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied Kum'isha with another fragment.",["sourceHash"]="18c2050c5b19a544dd17d272a0931a0d83dafea90e1fb9051fc6dba3d239ab3d",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3504]={["aftermath"]="Ag'tor knew forces had not returned but distinguished presumed deaths from possible desertion.",["atomIDs"]={"3504:description:1-26","3504:description:28-77","3504:description:82-117","3504:description:119-140","3504:description:142-173","3504:description:178-223","3504:description:225-239","3504:description:241-316","3504:description:318-366","3504:description:371-431","3504:description:433-489","3504:description:491-510","3504:objective:1-57"},["endingAtomIDs"]={"3504:completion:1-83","3504:completion:85-113","3504:completion:115-176","3504:completion:178-185","3504:completion:190-273","3504:completion:275-338","3504:completion:343-370"},["opening"]="Belgrom blamed a trusted treasure seeker for warriors who had not returned. His demand for vengeance went through Ag'tor, since he said he could spare no additional force.",["pending"]="{actor} planned to carry the sealed letter to Valormok.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Belgrom's message.",["sourceHash"]="0584873acd089a96d8eabc24b9a296e00b4e7bc0e73df764411c59d26f047121",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3505]={["aftermath"]="A marked page's diagram matched the nearby crystals and circle.",["atomIDs"]={"3505:description:1-18","3505:description:23-126","3505:description:128-203","3505:description:208-311","3505:description:313-389","3505:description:391-441","3505:description:443-501","3505:objective:1-97","3505:objective:99-212"},["endingAtomIDs"]={"3505:completion:1-112","3505:completion:117-203","3505:completion:205-394"},["opening"]="Ag'tor began retaliation against the workers rather than their traveling mistress. After the attack, her personal camp might reveal something valuable enough to draw her into a confrontation.",["pending"]="{actor} meant to confront the workers and inspect Rimtori's camp.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the attack and found the camp's clue.",["sourceHash"]="62d660d11fb70970e575f2434e441384238ee77f33cc33edf3a80f31143fa2f0",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3506]={["aftermath"]="Ag'tor welcomed the defeat and expected Belgrom's satisfaction.",["atomIDs"]={"3506:description:1-232","3506:description:237-419","3506:description:424-487","3506:objective:1-76","3506:objective:78-151"},["endingAtomIDs"]={"3506:completion:1-5","3506:completion:7-17","3506:completion:22-36","3506:completion:38-61","3506:completion:63-124","3506:completion:126-139"},["opening"]="The diagram distinguished a crystal bound to the circle's creator from others linked to something darker. Breaking the personal focus offered a way to provoke Rimtori herself.",["pending"]="{actor} intended to break the focus and recover Rimtori's head.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the head to Ag'tor.",["sourceHash"]="14d9ed9a8aac43cb94b9596046b59c1509fa49f02a6cee7f05eeaf6729183042",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3507]={["aftermath"]="Belgrom's response was triumphant vengeance against the woman he accused of betrayal.",["atomIDs"]={"3507:description:1-31","3507:description:33-73","3507:description:75-101","3507:description:106-135","3507:description:137-164","3507:objective:1-39"},["endingAtomIDs"]={"3507:completion:1-5","3507:completion:7-38","3507:completion:40-62","3507:completion:67-80","3507:completion:82-119","3507:completion:121-147","3507:completion:152-201","3507:completion:203-239","3507:completion:244-309","3507:completion:314-318","3507:completion:320-355","3507:completion:357-395","3507:completion:397-435"},["opening"]="Ag'tor sent the news back to the man whose expedition had begun the grievance. Belgrom wanted to see the head himself before the agents followed home.",["pending"]="{actor} planned to report to Belgrom.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned with the evidence.",["sourceHash"]="42933f9322ae88fa9e75e8f431f5f12f4ac13c0e7cf9413f8f0651b9c9c87e75",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3508]={["aftermath"]="The ritual established the need to discover the beast's name.",["atomIDs"]={"3508:description:1-22","3508:description:24-134","3508:description:136-205","3508:description:210-324","3508:description:329-384","3508:description:386-459","3508:objective:1-53"},["endingAtomIDs"]={"3508:completion:1-36"},["opening"]="Loramus agreed to help expose the demon's servants to harm. Rare artifacts would be needed, but first an enlightenment ritual had to establish the knowledge for the weapons.",["pending"]="{actor} intended to wait through the enlightenment.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} remained for Loramus's spell.",["sourceHash"]="16dd748837e4c2ede81729881b57a14055c49ee1898a540b67f0903dc305b83e",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3509]={["aftermath"]="Arkkoroc made assistance conditional on a service of his own.",["atomIDs"]={"3509:description:1-61","3509:description:63-117","3509:description:122-202","3509:description:207-255","3509:description:257-363","3509:description:368-430","3509:objective:1-36","3509:objective:38-105"},["endingAtomIDs"]={"3509:completion:1-13","3509:completion:18-40","3509:completion:45-133"},["opening"]="A true name forged into a weapon could make the demon and his servants vulnerable. Loramus sent the search toward a lesser deity, warning that knowledge would likely demand payment.",["pending"]="{actor} planned to seek Arkkoroc at his temple.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reached the lord of Arkkoran.",["sourceHash"]="32d871002a9e0258a1a48c5a14eb767086bd1eeddc19a8c2d63d23cf2c167948",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3510]={["atomIDs"]={"3510:description:1-30","3510:description:32-80","3510:description:82-107","3510:description:109-150","3510:description:155-244","3510:description:249-271","3510:description:273-294","3510:description:299-338","3510:objective:1-120"},["opening"]="Arkkoroc accused Hetaera of killing his children and falsely claiming the oceans. All three heads were his demanded price for the name and another essential aid.",["pending"]="{actor} meant to return Hetaera's three heads.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the heads to Arkkoroc.",["sourceHash"]="2fc0d529491ed77f967f9d1f6d28f84a27ad53330537f5f56b63cf73e210dd95",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3511]={["aftermath"]="Loramus accepted the temper's needed properties and identified one step still remaining.",["atomIDs"]={"3511:description:1-76","3511:description:78-156","3511:description:161-208","3511:description:210-262","3511:description:267-361","3511:description:366-441","3511:objective:1-43"},["endingAtomIDs"]={"3511:completion:1-84","3511:completion:86-130"},["opening"]="Arkkoroc supplied the true name Rakh'likh and drained the heads for a temper. Both knowledge and substance were to return to Loramus for the weapon's next stage.",["pending"]="{actor} intended to take the temper and name to Loramus.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Arkkoroc's contribution.",["sourceHash"]="765b91f0eb3b2c63901892c4f809d0985093c56d4f56394f692f49f19dc16d10",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3512]={["aftermath"]="Umbranse could not yet help directly: his strongest augury device had been taken and first needed recovery.",["atomIDs"]={"3512:description:1-85","3512:description:88-183","3512:description:186-275","3512:description:280-393","3512:description:396-440","3512:description:443-506","3512:objective:1-85"},["endingAtomIDs"]={"3512:completion:1-36","3512:completion:38-134","3512:completion:136-180","3512:completion:182-198","3512:completion:203-343","3512:completion:345-477"},["opening"]="Itharius sought a means to speak through Eranikus's tainted essence. Umbranse's skill with the dead might help a dragon caught between sleep and death.",["pending"]="{actor} planned to consult Umbranse in Winterspring.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reached the spiritspeaker.",["sourceHash"]="39b0383b757788165a203b28920713d6f9b80e26cd22afde81e12fc84f610516",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3513]={["atomIDs"]={"3513:description:1-69","3513:description:71-134","3513:description:139-301","3513:objective:1-65"},["opening"]="A silver ribbon enclosed an official-looking scroll. The northern outpost near Ashenvale offered a place to learn whether its information concerned the night elves.",["pending"]="{actor} meant to take the scroll to the guard tower.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} presented the scroll to Kadrak.",["sourceHash"]="3a680d4f0f75b872ebb50c10881e90be1e2d57254bcea20ea53d93bbe6e9dff4",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3514]={["aftermath"]="Kadrak expected the den to regroup slowly and hoped for fewer runners through the Barrens.",["atomIDs"]={"3514:description:1-98","3514:description:103-220","3514:description:222-269","3514:description:274-301","3514:description:303-359","3514:description:361-385","3514:description:387-503","3514:objective:1-59"},["endingAtomIDs"]={"3514:completion:1-19","3514:completion:21-70","3514:completion:72-161","3514:completion:163-216","3514:completion:221-230"},["opening"]="Kadrak identified the scroll with Rynthariel of the Talon Den. He ordered a strike at its leader and a Horde flag displayed against further messengers.",["pending"]="{actor} planned to confront Rynthariel at the den.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed Kadrak's assignment against Rynthariel.",["sourceHash"]="2fd93465d2adfcbe0b806a643fe985a0fc7c7fd0ef5a6a6788ee9064acd2d53d",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3517]={["aftermath"]="Their good condition pleased Jediga, who was ready to begin the deliveries.",["atomIDs"]={"3517:description:1-59","3517:description:61-111","3517:description:116-218","3517:description:223-332","3517:description:337-411","3517:description:413-455","3517:description:457-497","3517:objective:1-142"},["endingAtomIDs"]={"3517:completion:1-40","3517:completion:42-105","3517:completion:110-165","3517:completion:167-193"},["opening"]="Jediga had turned punishment in Azshara into opportunity. Four wizard-named tablets among Eldarath's ruins already had prospective buyers, making recovery the beginning of several separate bargains.",["pending"]="{actor} planned to gather all four tablets.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the tablets to Jediga.",["sourceHash"]="08b033702643a315ec811b21d43ba29a63fd64759740fa29172632642b74ba47",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3518]={["aftermath"]="Magatha recognized the influential alchemist's work and welcomed the success of her arrangement with Jediga.",["atomIDs"]={"3518:description:1-43","3518:description:45-63","3518:description:65-187","3518:description:189-314","3518:description:319-353","3518:description:355-431","3518:description:433-449","3518:objective:1-59"},["endingAtomIDs"]={"3518:completion:1-43","3518:completion:45-151","3518:completion:153-181","3518:completion:186-251","3518:completion:253-333"},["opening"]="Jediga said Magatha hoped Highborne knowledge could help the Forsaken, while qualifying that explanation as the elder's claim. Beth'Amara's tablet was the object promised to Thunder Bluff.",["pending"]="{actor} meant to deliver Beth'Amara's tablet.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought it to Magatha.",["sourceHash"]="5e9a31d8d3255fe490757d671396e6be8c8669f428c500b267d51cf3914e4e5b",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3519]={["atomIDs"]={"3519:description:1-8","3519:description:10-120","3519:description:122-180","3519:description:185-216","3519:description:218-245","3519:description:250-257","3519:description:259-273","3519:objective:1-43"},["opening"]="Iverron said Githyiss the Vile bit him in the nearby spider cave. Dizzy and fearing serious poison, he urgently asked for word to be taken to Dirania Silvershine.",["pending"]="{actor} would tell Dirania Silvershine of Iverron's condition.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reached Dirania Silvershine with Iverron's plea.",["sourceHash"]="e5c489424f37178c7e5a66d9b768d4de683df3e704275e0f3503531ee8bd5a91",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3520]={["aftermath"]="Yeh'kinya disclosed a prophecy about Hakkar's return, dismissing the myth while stressing the power in the god's essence. His stated purpose was keeping that power from misuse.",["atomIDs"]={"3520:description:1-53","3520:description:56-132","3520:description:137-177","3520:description:180-290","3520:description:293-337","3520:description:340-380","3520:description:385-502","3520:objective:1-94"},["endingAtomIDs"]={"3520:completion:1-23","3520:completion:26-65","3520:completion:70-193","3520:completion:196-330","3520:completion:335-479"},["opening"]="Yeh'kinya claimed Feralas's screechers were kin to an ancient god. His bramble wand could reveal the spirits of fallen birds, and three collected essences were the price of hearing more.",["pending"]="{actor} meant to capture three Screecher Spirits and return them with Yeh'kinya's bramble.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the three-spirit collection and returned to Yeh'kinya.",["sourceClassMask"]="?",["sourceHash"]="79a7cd0a92add0e26661b2830affb43f76001f4da25bb98edff5c26552762952",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3523]={["aftermath"]="Belnistrasz accepted the help and prepared to explain the dangerous work still ahead.",["atomIDs"]={"3523:description:1-12","3523:description:15-70","3523:description:73-105","3523:description:107-160","3523:description:163-284","3523:description:289-297","3523:description:299-370","3523:description:373-418","3523:description:421-506","3523:objective:1-101"},["endingAtomIDs"]={"3523:completion:1-54","3523:completion:56-121","3523:completion:123-199","3523:completion:204-263"},["opening"]="Belnistrasz gave thanks for rescue but refused simply to flee Razorfen Downs. He blamed a pact between the quilboar and the Scourge for the nightmare there and asked for help changing it.",["pending"]="{actor} planned to return the Oathstone and agree to aid Belnistrasz.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the Oathstone and pledged aid to Belnistrasz.",["sourceClassMask"]="?",["sourceHash"]="a179e8d3bef86ca7c1adf450a0acadbd28bded0dfdfa0efeebf83872ab8088d7",["sourceMapID"]="?",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3524]={["atomIDs"]={"3524:description:1-111","3524:description:113-185","3524:description:188-324","3524:description:329-436","3524:description:439-508","3524:objective:1-144"},["opening"]="Gwennyth studied the increasing number of sea creatures beaching themselves along Darkshore. Murlocs hampered the Temple of the Moon's investigation, including access to the giant carcass just south of Auberdine.",["pending"]="{actor} meant to recover Sea Creature Bones from the southern carcass for Gwennyth.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Sea Creature Bones from the specified beached creature to Gwennyth.",["sourceHash"]="744aa49c2dbbc084db686a4bc522d107aa1e6ee09d742fb0eb5de5ced41ac48b",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3525]={["aftermath"]="Belnistrasz vanished, leaving a burning brazier and the image of a red dragon. His voice credited the defenders with ending the butchery at the idol.",["atomIDs"]={"3525:description:1-93","3525:description:95-150","3525:description:153-244","3525:description:247-277","3525:description:280-320","3525:description:323-391","3525:description:394-431","3525:description:434-481","3525:description:486-502","3525:objective:1-60","3525:objective:65-135"},["endingAtomIDs"]={"3525:completion:1-65","3525:completion:68-152","3525:completion:155-224","3525:completion:229-289","3525:completion:292-372","3525:completion:375-438","3525:completion:441-483"},["opening"]="Belnistrasz described an idol used as an oven for abducted people. He could bind it against further use, but the ritual would leave him unable to defend himself.",["pending"]="{actor} intended to escort Belnistrasz to the idol and protect his ritual.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed Belnistrasz's escort and protected the ritual at the quilboar idol.",["sourceClassMask"]="?",["sourceHash"]="088fa312d13ee9847fae89ec72e45b0c85fa964a72d3d55f1b0b1d2521a9ae34",["sourceMapID"]="?",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3526]={["aftermath"]="Nixx welcomed the prospective pupil while insisting that his explosive discipline required both intellect and steady hands.",["atomIDs"]={"3526:description:1-69","3526:description:72-140","3526:description:143-232","3526:description:237-257","3526:description:260-355","3526:description:359-497","3526:objective:1-131"},["endingAtomIDs"]={"3526:completion:1-43","3526:completion:45-176","3526:completion:178-293","3526:completion:298-353"},["opening"]="Graham Van Talen favored goblin engineering's explosives and ambitious gear. His manual offered a route to Nixx in Gadgetzan and described the choice of specialization as permanent.",["pending"]="{actor} meant to take the Manual of Engineering Disciplines to Nixx Sprocketspring.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.",["sourceClassMask"]="?",["sourceHash"]="d7fb1ec32b0c513f9743c46c16171d2f9f03fce35c61e55d24f97ad47e8766fe",["sourceMapID"]="?",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3527]={["aftermath"]="Yeh'kinya planned to fuse the tablets and study their concealed meanings. Their recovery gave him the material for the next part of his undertaking.",["atomIDs"]={"3527:description:1-85","3527:description:88-178","3527:description:183-212","3527:description:217-281","3527:description:284-368","3527:description:373-462","3527:description:467-510","3527:objective:1-68"},["bridge"]="The screecher spirits had reached Yeh'kinya. He now asked for Mosh'aru's two tablets from Zul'Farrak, presenting the prophecy as a means to contain Hakkar's essence.",["bridgeFrom"]=3520,["bridgeReplacesSetup"]=true,["endingAtomIDs"]={"3527:completion:1-17","3527:completion:19-97","3527:completion:102-126","3527:completion:128-158"},["opening"]="Yeh'kinya presented Mosh'aru's prophecy as a way to contain Hakkar's essence. Its two tablets were held in Zul'Farrak by Theka and Velratha, placing the next stage of his plan among the sand trolls.",["pending"]="{actor} intended to recover the First and Second Mosh'aru Tablets.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the First and Second Mosh'aru Tablets to Yeh'kinya.",["sourceClassMask"]="?",["sourceHash"]="4fa7b05044c3f512d4097904f04f71689e60c21d5c8fef1366fd2e2ab017a9d5",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3528]={["aftermath"]="The egg stirred. Yeh'kinya feared the implications of the old myths, promised to keep it safe, and declared the work with him finished.",["atomIDs"]={"3528:description:1-62","3528:description:67-154","3528:description:157-200","3528:description:205-241","3528:description:244-370","3528:description:373-442","3528:description:447-505","3528:objective:1-55"},["endingAtomIDs"]={"3528:completion:1-41","3528:completion:43-75","3528:completion:77-110","3528:completion:115-195","3528:completion:197-267","3528:completion:272-308","3528:completion:310-394"},["opening"]="Yeh'kinya directed the Egg of Hakkar toward the Sunken Temple. Blood from the god's minions would quench the binding flames, allowing an avatar to emerge so its essence could be captured.",["pending"]="{actor} planned to return the Filled Egg of Hakkar to Yeh'kinya.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Filled Egg of Hakkar to Yeh'kinya in Tanaris.",["sourceClassMask"]="?",["sourceHash"]="60fae1411ca356f80705bbf72d6a4a937532ab7fee3087e91d89180445485c6b",["sourceMapID"]="?",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3541]={["aftermath"]="Jes'rimon welcomed both its arrival and its unspoiled condition.",["atomIDs"]={"3541:description:1-28","3541:description:30-52","3541:description:54-213","3541:description:218-345","3541:description:350-413","3541:description:415-506","3541:objective:1-55"},["endingAtomIDs"]={"3541:completion:1-61","3541:completion:63-67","3541:completion:69-89","3541:completion:94-128","3541:completion:130-140","3541:completion:142-162","3541:completion:167-181","3541:completion:183-217","3541:completion:219-248"},["opening"]="A discreet contact in Orgrimmar had offered a good price for Jin'yael's tablet. Jediga did not know his purpose and warned against advertising his business.",["pending"]="{actor} intended to find Jes'rimon with the tablet.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered it in the Drag.",["sourceHash"]="798bde2282e33feeb18867180c056c16b3fd8ca724f020f8fdbe7ba1012fe2da",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3542]={["atomIDs"]={"3542:description:1-31","3542:description:33-79","3542:description:81-108","3542:description:113-207","3542:description:209-316","3542:description:318-355","3542:description:357-419","3542:description:424-494","3542:objective:1-55"},["opening"]="Andron's bargain was less secretive about purpose: Undercity mages wanted Highborne spells. Markri's skill at summoning made his tablet valuable for their study.",["pending"]="{actor} planned to deliver Markri's tablet.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the object to Andron.",["sourceHash"]="d2f62719ea8f0258331f3787191cad970a11c688224e0f80e307e773f29a33bd",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3561]={["aftermath"]="Xylem welcomed the chance to study the tablet and confirmed Jediga's price worthwhile.",["atomIDs"]={"3561:description:1-53","3561:description:55-157","3561:description:162-224","3561:description:226-274","3561:description:276-285","3561:description:287-365","3561:description:370-482","3561:description:484-505","3561:objective:1-58"},["endingAtomIDs"]={"3561:completion:1-29","3561:completion:31-63","3561:completion:68-81","3561:completion:83-125","3561:completion:127-182"},["opening"]="Jediga distrusted Xylem most of all her buyers and dared not ask his purpose. Sanath could arrange access to the powerful mage's tower for the final tablet delivery.",["pending"]="{actor} meant to take Sael'hai's tablet to Xylem.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered it at the tower.",["sourceHash"]="138dc76c06a00e198b5ea8d25d9247131d5b42b693298af140d4a9de21c67827",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3562]={["aftermath"]="Jediga was surprised the substitute messenger had met no punishment and wondered at Magatha's eagerness for the tablet.",["atomIDs"]={"3562:description:1-25","3562:description:27-85","3562:description:87-126","3562:description:131-145","3562:description:147-191","3562:objective:1-44"},["endingAtomIDs"]={"3562:completion:1-9","3562:completion:11-57","3562:completion:59-79","3562:completion:81-169","3562:completion:171-203","3562:completion:205-216","3562:completion:221-253"},["opening"]="Magatha sent a note confirming her satisfaction. Payment awaited Jediga's own return, so the messenger carried assurance rather than a claim that the elder had already paid her in person.",["pending"]="{actor} intended to return Magatha's note.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered it to Jediga.",["sourceHash"]="cf5c95337017b255c12897cc08d1437765c09d821aaef2e0a9f651a9d716bf06",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3563]={["aftermath"]="Jediga read his advances as excessive and found another reason to remain in Azshara.",["atomIDs"]={"3563:description:1-27","3563:description:29-106","3563:description:111-204","3563:description:209-286","3563:objective:1-46"},["endingAtomIDs"]={"3563:completion:1-63","3563:completion:65-85","3563:completion:90-183","3563:completion:185-267","3563:completion:272-304"},["opening"]="Jes'rimon's letter joined business approval with a personal invitation. Jediga was to hear that the deal pleased him and that he wanted her back in Orgrimmar.",["pending"]="{actor} planned to take Jes'rimon's note to Jediga.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the letter.",["sourceHash"]="97596f66351eff5260d9c31abaa95bb94fd040ac8e114a4a0b13e8ff54af3ab8",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3564]={["aftermath"]="Jediga found that Andron had overpaid, speculating about a changed bargain or drunkenness without settling the cause. She offered the courier an additional share.",["atomIDs"]={"3564:description:1-7","3564:description:9-15","3564:description:17-37","3564:description:39-54","3564:objective:1-43"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"3564:completion:1-10","3564:completion:12-25","3564:completion:30-34","3564:completion:36-89","3564:completion:91-118","3564:completion:120-144","3564:completion:146-179","3564:completion:181-202","3564:completion:207-223","3564:completion:225-255"},["minimumStage"]=2,["objectiveSummary"]="Take Andron's note to Jediga in Azshara.",["opening"]="Andron passed over a note for Jediga between hiccups. Carrying the message would close the exchange by returning his answer to the contact in Azshara.",["pending"]="{actor} would deliver Andron's note to Jediga.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} handed the note to Jediga.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="1d7ccf4ed99f095f14c3fdbe9587f1521a7f6c508f660cf15d81d9673ad5fde0",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[3565]={["aftermath"]="The lack of trouble surprised her and made her reconsider whether the mage could be trusted.",["atomIDs"]={"3565:description:1-11","3565:description:13-33","3565:description:35-44","3565:description:49-78","3565:description:80-139","3565:objective:1-42"},["endingAtomIDs"]={"3565:completion:1-12","3565:completion:14-25","3565:completion:27-62","3565:completion:64-141","3565:completion:143-181","3565:completion:186-224","3565:completion:226-243","3565:completion:245-268"},["opening"]="Xylem released a note for the waiting organizer after the tablet delivery. The return completed this leg of a bargain Jediga had expected might be betrayed.",["pending"]="{actor} meant to bring Xylem's note back.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the note to Jediga.",["sourceHash"]="403b764e2d6cafe999c69c063bd0afe519362f804d12b879bd23db8dcddb66aa",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3566]={["aftermath"]="Thorius recognized his brother's betrayal and feared the influence of Ragnaros could turn even those he had considered honorable.",["atomIDs"]={"3566:description:13-30","3566:description:35-44","3566:description:53-71","3566:description:73-90","3566:description:92-103","3566:objective:1-135"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"3566:completion:1-28","3566:completion:33-39","3566:completion:41-55","3566:completion:57-71","3566:completion:73-91","3566:completion:96-129","3566:completion:134-171","3566:completion:173-248","3566:completion:250-371"},["minimumStage"]=2,["objectiveSummary"]="Defeat Lathoric and Obsidion, then bring their head and heart to Thorius.",["opening"]="The rescue had been a trap. The dying plea called for vengeance on the betrayer and for Thorius to learn what had happened, directing the confrontation toward Lathoric the Black and Obsidion.",["pending"]="{actor} would confront Lathoric and Obsidion and carry proof to Thorius.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought Lathoric's head and Obsidion's heart to Thorius.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="3246d9df7798ddc85d980fccae70580d59c1e3e221461929c15aa2d1ada219a0",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[3568]={["aftermath"]="Cuely began preparing a test while noting that Thersa remained gravely ill.",["atomIDs"]={"3568:description:1-86","3568:description:88-115","3568:description:117-207","3568:description:212-312","3568:description:314-342","3568:description:344-362","3568:description:367-402","3568:description:404-455","3568:description:457-499","3568:objective:1-127"},["endingAtomIDs"]={"3568:completion:1-10","3568:completion:12-39","3568:completion:41-51","3568:completion:56-96","3568:completion:101-171","3568:completion:173-207","3568:completion:209-263","3568:completion:265-286","3568:completion:291-355","3568:completion:357-363"},["opening"]="Thersa became ill after a fight and a drink from Azshara's tide pools. Cuely sought samples from four pools before deciding what she had swallowed and how to test a remedy.",["pending"]="{actor} intended to fill all four labeled vials.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the coastal water samples.",["sourceHash"]="fe11380a3028d9a5805cdf682b238cebf5601b73f803f8b28c177e550f3dd492",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3569]={["aftermath"]="Thersa distrusted the accommodating chemist but saw no alternative after priests and shamans failed to help.",["atomIDs"]={"3569:description:1-20","3569:description:22-48","3569:description:50-61","3569:description:63-109","3569:objective:1-52"},["endingAtomIDs"]={"3569:completion:1-44","3569:completion:46-61","3569:completion:63-124","3569:completion:126-170","3569:completion:172-243","3569:completion:248-303"},["opening"]="Cuely could not promise the new mixture would cure Thersa. Giving it to her was the next experiment, with the result dependent on what followed drinking it.",["pending"]="{actor} planned to bring the elixir to Thersa.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Cuely's preparation.",["sourceHash"]="610f0ce045e152761e59a69a7adab138d59c121898cc24f5a9787e1d33e49b67",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3601]={["atomIDs"]={"3601:description:1-17","3601:description:19-73","3601:description:75-87","3601:description:89-111","3601:description:113-128","3601:description:133-214","3601:description:216-370","3601:description:379-424","3601:description:429-497","3601:description:499-510","3601:objective:1-132"},["opening"]="Kim'jael said treasure-seeking employers had turned on him and kept his equipment. Recovery from their camp mattered more immediately than the insult he attached to his name.",["pending"]="{actor} intended to recover all four personal objects.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the compass, scope, chicken and wizzlegoober.",["sourceHash"]="09626e8f372720e89cc1df8a55a837adf3184bcbb8dcbfaadcf59e706fded4f5",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3602]={["aftermath"]="Loramus declared the local tasks complete and turned toward forging the gathered components.",["atomIDs"]={"3602:description:1-117","3602:description:119-225","3602:description:230-346","3602:description:351-449","3602:description:451-503","3602:objective:1-60","3602:objective:62-159","3602:objective:164-207"},["endingAtomIDs"]={"3602:completion:1-43","3602:completion:45-122"},["opening"]="Azsharite formed after giants consumed the region's stone. Loramus needed the strong, malleable crystal for the weapon's body and offered a felhound's nose to help find deposits among hostile giants.",["pending"]="{actor} planned to gather twenty crystals.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the azsharite to Loramus.",["sourceHash"]="73de6554f293fb994d32ef46f507ec29fed6c13d243b6c18fdb82fd836ab0e3b",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3621]={["atomIDs"]={"3621:description:1-35","3621:description:37-119","3621:description:124-170","3621:description:172-266","3621:description:268-342","3621:description:347-409","3621:description:411-475","3621:objective:1-62"},["opening"]="The tempered crystal was ready, but its shaping required a smith able to harness fel energy. Loramus named Galvan of the Mithril Order in Stranglethorn.",["pending"]="{actor} meant to carry the shipment to Galvan.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the tempered materials to the smith.",["sourceHash"]="22a6549a20a6d5d4b2e97bbede77e12e4bf2396e13b3e63ca860ac474d995288",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3625]={["aftermath"]="Galvan finished his forging work and praised the resulting demon-slaying weapon. Its creation prepared a confrontation still to come.",["atomIDs"]={"3625:description:1-52","3625:description:57-136","3625:description:138-235","3625:description:237-308","3625:description:313-358","3625:objective:1-47"},["endingAtomIDs"]={"3625:completion:1-39","3625:completion:44-86"},["opening"]="Galvan needed time to forge the fel weaponry. He warned that its curse could be released only once every three minutes and might weaken Razelikh's forces for an uncertain duration, making timing important for its eventual use.",["pending"]="{actor} planned to wait while Galvan forged the weaponry.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the wait for Galvan's forging work.",["sourceClassMask"]="?",["sourceHash"]="47471f8f686076f05284a0ae1f52b050c6a874e05ca5fb7a88bab6dc272424ba",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3626]={["aftermath"]="The Fallen Hero asked whether the traveler was prepared for Razelikh and his minions. The return began the final briefing rather than reporting that battle won.",["atomIDs"]={"3626:description:1-35","3626:description:37-178","3626:objective:1-39"},["bridge"]="Galvan's forging work had finished. The new weaponry was bound back to the Fallen Hero in the Blasted Lands, where the final objective against Razelikh awaited.",["bridgeFrom"]=3625,["bridgeReplacesSetup"]=true,["endingAtomIDs"]={"3626:completion:1-29","3626:completion:31-80"},["opening"]="Galvan sent the new weaponry back toward the Blasted Lands. The Fallen Hero of the Horde was to give the final objective in the struggle now nearing what Galvan called redemption.",["pending"]="{actor} meant to return to the Fallen Hero of the Horde.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with the Fallen Hero of the Horde in the Blasted Lands.",["sourceClassMask"]="?",["sourceHash"]="753bfa71367fad083943bf4277235019380121d21c97bd326fcac9ba42e3ee36",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3627]={["aftermath"]="The commander confirmed that the amulet was complete and warned that Razelikh sensed the loss of his servants.",["atomIDs"]={"3627:description:1-94","3627:description:96-184","3627:description:196-216","3627:description:218-255","3627:objective:1-61","3627:objective:63-156","3627:objective:161-234","3627:objective:236-291"},["endingAtomIDs"]={"3627:completion:1-111","3627:completion:113-140"},["opening"]="The triad still stood between the commander and Razelikh. Enchanted fel weapons were required to weaken the servants before their amulet pieces could be reclaimed.",["pending"]="{actor} meant to recover all three pieces with the enchanted weapons.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the three servants' amulets.",["sourceHash"]="708180f37a28670dea7b4d3560fa929b726d973a4e582b5f7058296e43562c02",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3628]={["aftermath"]="The fallen commander confirmed the demonic overlord's fall; the ward had also been returned for destruction.",["atomIDs"]={"3628:description:1-66","3628:description:68-151","3628:description:153-224","3628:description:226-277","3628:description:279-305","3628:description:307-341","3628:description:346-396","3628:description:398-502","3628:objective:1-104","3628:objective:106-251"},["endingAtomIDs"]={"3628:completion:1-56","3628:completion:58-118"},["opening"]="The completed amulet opened a way through teleport runes to the mountain lair. It also served to summon Razelikh at his altar.",["pending"]="{actor} intended to confront Razelikh and return the horn and ward.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the severed horn and the ward.",["sourceHash"]="c8b14851be15e4ce8f028ea3d606a0c087b1e88034c66177fd39cc322e0626bb",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3629]={["aftermath"]="Nixx answered the prospective pupil with his own disdain for gnomish basics. He emphasized the steady hand his discipline demanded.",["atomIDs"]={"3629:description:1-69","3629:description:72-142","3629:description:145-241","3629:description:246-266","3629:description:269-363","3629:description:367-505","3629:objective:1-131"},["endingAtomIDs"]={"3629:completion:1-43","3629:completion:45-176","3629:completion:178-293","3629:completion:298-353"},["opening"]="Springspindle Fizzlegear reluctantly presented the goblin branch of engineering. He mocked its appetite for explosions, yet supplied the manual and Nixx's Gadgetzan address for anyone choosing that path.",["pending"]="{actor} intended to take the Manual of Engineering Disciplines to Nixx Sprocketspring.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.",["sourceClassMask"]="?",["sourceHash"]="02b273058707a2a54ea77e785982fc9d33ee57777ac31cdd34951fdd725ec9c2",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3630]={["aftermath"]="Overspark welcomed another engineer despite the difficult circumstances surrounding his people.",["atomIDs"]={"3630:description:1-78","3630:description:81-140","3630:description:143-225","3630:description:230-250","3630:description:253-359","3630:description:363-492","3630:objective:1-131"},["endingAtomIDs"]={"3630:completion:1-84","3630:completion:86-119","3630:completion:121-256"},["opening"]="Lilliam Sparkspindle praised gnome engineering as a means of improving life through devices. Her manual directed a prospective specialist to Overspark and warned that joining excluded the competing discipline.",["pending"]="{actor} meant to carry the Manual of Engineering Disciplines to Tinkmaster Overspark.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge.",["sourceClassMask"]="?",["sourceHash"]="52fede70e051629575c60f2f352409397c6c332f377c3561a454c77568c23f13",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3631]={["atomIDs"]={"3631:description:1-5","3631:description:7-61","3631:description:63-120","3631:description:122-131","3631:description:136-174","3631:description:176-271","3631:description:276-294","3631:objective:1-39"},["opening"]="Zevrost doubted a pupil's readiness, but Strahad had decided otherwise. The summons required a prompt visit to the warlock's tower above Ratchet, where his acolytes remained.",["pending"]="{actor} planned to speak with Strahad Farsan above Ratchet.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} answered Strahad Farsan's summons in the Barrens.",["sourceClassMask"]="256",["sourceHash"]="aa210fb5f80208c959f1d62061589d207be491ca498bd2e1b762fe375f2bae41",["sourceMapID"]="?",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3632]={["aftermath"]="Overspark greeted the interest in his discipline with theatrical enthusiasm, then acknowledged the gravity of his people's situation.",["atomIDs"]={"3632:description:1-78","3632:description:81-140","3632:description:143-225","3632:description:230-250","3632:description:253-364","3632:description:368-497","3632:objective:1-131"},["endingAtomIDs"]={"3632:completion:1-84","3632:completion:86-119","3632:completion:121-256"},["opening"]="Springspindle presented gnome engineering as the superior way to build useful devices. The manual sent its reader to Overspark in Ironforge, with a warning about the lasting choice between disciplines.",["pending"]="{actor} intended to take the Manual of Engineering Disciplines to Tinkmaster Overspark.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge.",["sourceClassMask"]="?",["sourceHash"]="898bbbefc7d66f3471abfa38ebffcc647e3fc90ae1d18b3ee873f2842f04ff78",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3633]={["aftermath"]="Nixx offered instruction while contrasting the discipline's demands with what he dismissed as ordinary engineering.",["atomIDs"]={"3633:description:1-69","3633:description:72-140","3633:description:143-232","3633:description:237-257","3633:description:260-355","3633:description:359-497","3633:objective:1-131"},["endingAtomIDs"]={"3633:completion:1-43","3633:completion:45-176","3633:completion:178-293","3633:completion:298-353"},["opening"]="Tinkerwiz recommended goblin engineering for its powerful gear and explosives. A manual introduced the discipline, and Nixx in Gadgetzan could explain the commitment it required.",["pending"]="{actor} meant to bring the Manual of Engineering Disciplines to Nixx Sprocketspring.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.",["sourceClassMask"]="?",["sourceHash"]="7bbfb0289280e9f87f30d6397034b91cde6cddfc5e7242768426119c4efca66c",["sourceMapID"]="?",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3634]={["aftermath"]="Overspark's welcome gave a very different account of gnome engineering's worth from Tinkerwiz's contempt.",["atomIDs"]={"3634:description:1-78","3634:description:81-153","3634:description:156-237","3634:description:242-262","3634:description:265-377","3634:description:381-510","3634:objective:1-131"},["endingAtomIDs"]={"3634:completion:1-84","3634:completion:86-119","3634:completion:121-256"},["opening"]="Tinkerwiz grudgingly explained the gnomish specialization, dismissing its devices as unreliable. Anyone willing to pursue it despite that judgment could take the manual to Overspark in Ironforge.",["pending"]="{actor} planned to take the Manual of Engineering Disciplines to Tinkmaster Overspark.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge.",["sourceClassMask"]="?",["sourceHash"]="2fa6b6e5a55646d4be524d97e289c9307a57b4253a971c8144b449afa6229f8d",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3635]={["aftermath"]="Oglethorpe attributed his estrangement from Gnomeregan to politics and intellectual rivalry. He offered his knowledge to a capable pupil.",["atomIDs"]={"3635:description:1-78","3635:description:81-153","3635:description:156-231","3635:description:236-256","3635:description:259-370","3635:description:374-503","3635:objective:1-131"},["endingAtomIDs"]={"3635:completion:1-49","3635:completion:51-87","3635:completion:89-258","3635:completion:263-372","3635:completion:374-429"},["opening"]="Graham Van Talen thought little of gnomish gadgets, but still supplied their path of study. Oglethorpe Obnoticus in Booty Bay was the contact named in his referral.",["pending"]="{actor} intended to carry the Manual of Engineering Disciplines to Oglethorpe Obnoticus.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Manual of Engineering Disciplines to Oglethorpe Obnoticus in Booty Bay.",["sourceClassMask"]="?",["sourceHash"]="72f0cc943521f21b214d7d560f4a4e57ac1d0ad3f318fd6788e7ad00533225d8",["sourceMapID"]="?",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3636]={["aftermath"]="Benedictus hoped the defeat would deter further attempts by the Scourge to enlarge its ranks.",["atomIDs"]={"3636:description:1-89","3636:description:91-152","3636:description:157-224","3636:description:226-369","3636:description:371-427","3636:description:432-496","3636:objective:1-82"},["endingAtomIDs"]={"3636:completion:1-15","3636:completion:17-94","3636:completion:99-130"},["opening"]="Benedictus warned of a Scourge pact within Razorfen Downs. The quilboar now served Amnennar the Coldbringer, and the archbishop called for an end to the alliance under the Light's banner.",["pending"]="{actor} meant to defeat Amnennar the Coldbringer in Razorfen Downs.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reported completion of the task against Amnennar the Coldbringer to Archbishop Benedictus.",["sourceClassMask"]="?",["sourceHash"]="258c54d3cc5e550bb2f6e0a5e63df77dee4614caf0dea94234ff0bfe19c8337f",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3637]={["aftermath"]="Oglethorpe claimed Gnomeregan had lost one of its finest engineers when he left. He was willing to teach a pupil who proved capable.",["atomIDs"]={"3637:description:1-78","3637:description:81-153","3637:description:156-231","3637:description:236-256","3637:description:259-370","3637:description:374-503","3637:objective:1-131"},["endingAtomIDs"]={"3637:completion:1-49","3637:completion:51-87","3637:completion:89-258","3637:completion:263-372","3637:completion:374-429"},["opening"]="Tinkerwiz derided the gnomish promise of world-changing gadgets. Even so, he provided a manual and a referral to Oglethorpe in Booty Bay for a prospective specialist willing to choose that route.",["pending"]="{actor} planned to take the Manual of Engineering Disciplines to Oglethorpe Obnoticus.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Manual of Engineering Disciplines to Oglethorpe Obnoticus in Booty Bay.",["sourceClassMask"]="?",["sourceHash"]="fa49f5392950727cb2131edf27772b94cedb0443599e32e2f31717a4d444e7fe",["sourceMapID"]="?",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3638]={["aftermath"]="Nixx accepted the commitment and turned toward examining the new member's engineering work.",["atomIDs"]={"3638:description:1-86","3638:description:89-187","3638:description:192-260","3638:description:263-309","3638:description:312-358","3638:description:363-479","3638:description:482-510","3638:objective:1-142"},["endingAtomIDs"]={"3638:completion:1-35","3638:completion:37-124","3638:completion:129-259","3638:completion:261-344"},["opening"]="Nixx placed profit and explosive force at the heart of his engineering. Entry required a lifelong pledge to keep its designs secret, with the manual's warning that the competing specialization would be closed.",["pending"]="{actor} intended to sign the Pledge of Secrecy and speak again with Nixx.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} signed the Pledge of Secrecy and confirmed the commitment to Nixx Sprocketspring.",["sourceClassMask"]="?",["sourceHash"]="b4436dddd977ac36ce24e2faf19fcf19c3606954ff0a71fab9b18303b619e90c",["sourceMapID"]="?",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3639]={["aftermath"]="Nixx issued a membership card with fourteen days of dues paid. He explained that lapses restricted new designs without erasing knowledge already learned.",["atomIDs"]={"3639:description:1-44","3639:description:47-106","3639:description:109-221","3639:description:224-356","3639:description:361-509","3639:objective:1-102"},["endingAtomIDs"]={"3639:completion:1-51","3639:completion:56-162","3639:completion:164-356","3639:completion:361-451"},["opening"]="Nixx wanted working samples to assess how a pupil could develop goblin techniques. Bombs, dynamite, and explosive sheep would support that review, with their safeties still armed.",["pending"]="{actor} meant to bring twenty Big Iron Bombs, twenty Solid Dynamite, and five Explosive Sheep to Nixx.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered twenty Big Iron Bombs, twenty Solid Dynamite, and five Explosive Sheep to Nixx Sprocketspring.",["sourceClassMask"]="?",["sourceHash"]="d098a16fcdac36d585c505d98c1dbecffb201dc5f029a23808a1625dd3e250f4",["sourceMapID"]="?",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3640]={["aftermath"]="Overspark welcomed the new member and proposed examining practical work to guide further development.",["atomIDs"]={"3640:description:1-72","3640:description:75-179","3640:description:184-252","3640:description:255-300","3640:description:303-350","3640:description:355-470","3640:description:473-501","3640:objective:1-142"},["endingAtomIDs"]={"3640:completion:1-19","3640:completion:21-108","3640:completion:113-242","3640:completion:244-326"},["opening"]="Overspark described engineering theory shaped into devices that controlled the surrounding world. Joining his discipline required a lifelong promise of secrecy and acceptance of its exclusive specialization.",["pending"]="{actor} planned to sign the Pledge of Secrecy and speak again with Tinkmaster Overspark.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} signed the Pledge of Secrecy and confirmed the commitment to Tinkmaster Overspark.",["sourceClassMask"]="?",["sourceHash"]="a1c8a28e20de4facb9a4a8ce7c5cdcf3bc91d1b48773c026efa265ff83008b0b",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3641]={["aftermath"]="Overspark provided a membership card with two weeks of dues paid. Renewal governed access to further designs while existing knowledge remained intact.",["atomIDs"]={"3641:description:1-49","3641:description:52-111","3641:description:114-233","3641:description:236-335","3641:description:340-486","3641:objective:1-109"},["endingAtomIDs"]={"3641:completion:1-50","3641:completion:55-161","3641:completion:163-354","3641:completion:359-447"},["opening"]="Overspark needed samples with which to assess gnomish technique. Mithril tubes, a scope, and target dummies would demonstrate the work behind a prospective membership card.",["pending"]="{actor} intended to supply six Mithril Tubes, an Accurate Scope, and two Advanced Target Dummies.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered six Mithril Tubes, an Accurate Scope, and two Advanced Target Dummies to Tinkmaster Overspark.",["sourceClassMask"]="?",["sourceHash"]="fd47b68c06aa65383224f4e37f189a2f8d19e2e0abb7395fe324d2d5bb5121e3",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3642]={["aftermath"]="Oglethorpe accepted the commitment and moved on to a review of his new member's engineering work.",["atomIDs"]={"3642:description:1-72","3642:description:75-179","3642:description:184-252","3642:description:255-300","3642:description:303-350","3642:description:355-470","3642:description:473-501","3642:objective:1-142"},["endingAtomIDs"]={"3642:completion:1-19","3642:completion:21-108","3642:completion:113-242","3642:completion:244-326"},["opening"]="Oglethorpe offered gnome engineering as useful theory made tangible. Before teaching its guarded designs, he required a lifelong secrecy pledge and a considered commitment to that specialization.",["pending"]="{actor} meant to sign the Pledge of Secrecy and speak again with Oglethorpe Obnoticus.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} signed the Pledge of Secrecy and confirmed the commitment to Oglethorpe Obnoticus.",["sourceClassMask"]="?",["sourceHash"]="cd95c22f83eeb4e6e8530e811df159af35d5813d2244235bd2ce3103eeaed667",["sourceMapID"]="?",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3643]={["aftermath"]="Oglethorpe issued a membership card with fourteen days of dues paid. A lapse would suspend access to new designs, not remove those already known.",["atomIDs"]={"3643:description:1-49","3643:description:52-111","3643:description:114-233","3643:description:236-335","3643:description:340-486","3643:objective:1-111"},["endingAtomIDs"]={"3643:completion:1-50","3643:completion:55-161","3643:completion:163-354","3643:completion:359-447"},["opening"]="Oglethorpe asked to inspect the work of a skilled engineer through selected devices. The review would help direct future gnomish techniques and establish access to specialized trainers.",["pending"]="{actor} planned to bring six Mithril Tubes, an Accurate Scope, and two Advanced Target Dummies to Oglethorpe.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered six Mithril Tubes, an Accurate Scope, and two Advanced Target Dummies to Oglethorpe Obnoticus.",["sourceClassMask"]="?",["sourceHash"]="ebda9c7f33c9bea0875c3fb34fcdfe06395dcfaf2a6e6022531c2c98f7b0460e",["sourceMapID"]="?",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
