[3661]={["atomIDs"]={"3661:description:1-46","3661:description:48-171","3661:description:176-290","3661:description:295-412","3661:description:414-458","3661:description:460-504","3661:objective:1-91"},["opening"]="Rumor credited Elune with creating the wildkin, creatures capable of both gentleness and ferocity. Erelas wanted feathers from the Hinterlands' owlbeasts to investigate the claim rather than take it on faith.",["pending"]="{actor} would collect fifteen Wildkin Feathers in the Hinterlands for Erelas.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered fifteen Wildkin Feathers to Erelas Ambersky.",["sourceHash"]="aa04dcfc8412fc441077bdd9ca024a2e670669a0c9558d965522e427d5239711",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
