[3701]={["aftermath"]="Archesonus found the relic information useful and recognized that much still remained to learn about Thaurissan.",["atomIDs"]={"3701:description:1-112","3701:description:117-167","3701:description:169-215","3701:description:217-342","3701:objective:1-109","3701:objective:111-187"},["endingAtomIDs"]={"3701:completion:8-62","3701:completion:67-94"},["opening"]="Relics in Thaurissan's smoldering ruins might preserve the information Archesonus sought. Assassins guarded the buried secrets, making historical recovery a dangerous visit to the Burning Steppes.",["pending"]="{actor} intended to recover information from the Thaurissan Relics.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the relic-information assignment and returned to Royal Historian Archesonus.",["sourceClassMask"]="?",["sourceHash"]="d1b48a5eff0e2ad2de3108d9c6f79b4aa0aa783e6a87104fc5f85fe0268c4d7f",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[3702]={["atomIDs"]={"3702:description:1-64","3702:objective:1-70"},["opening"]="Archesonus offered a brief account of the Dark Iron dwarves. Before the ruins could be understood, their historian's story was available to hear.",["pending"]="{actor} planned to listen to Archesonus's history of Thaurissan.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the history conversation with Royal Historian Archesonus.",["sourceClassMask"]="?",["sourceHash"]="7ee5fe9ace58af4ef0470503d7e9a44fe536281d821915c874f24dcd6804b284",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
